mapper.select:
SELECT 
FROM user_notification n LEFT JOIN app_user actor ON actor.id = n.actor_id
WHERE n.id = #{id} AND n.recipient_id = #{recipientId}

SELECT 
FROM user_notification n LEFT JOIN app_user actor ON actor.id = n.actor_id
WHERE n.recipient_id = #{recipientId}
AND n.notification_type = #{type}
ORDER BY n.created_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM user_notification
WHERE recipient_id = #{recipientId}
AND notification_type = #{type}

mapper.update:
UPDATE user_notification SET read_at = #{readAt}
WHERE recipient_id = #{recipientId} AND read_at IS NULL
AND notification_type = #{type}

mapper.select:
SELECT id, participant_low_id, participant_high_id, last_message_at, created_at, updated_at
FROM direct_conversation
WHERE participant_low_id = #{participantLowId} AND participant_high_id = #{participantHighId}

SELECT 
FROM direct_message m JOIN app_user sender ON sender.id = m.sender_id
WHERE m.id = #{id}

SELECT 
FROM direct_message m JOIN app_user sender ON sender.id = m.sender_id
WHERE m.sender_id = #{senderId} AND m.client_message_id = #{clientMessageId}

SELECT 
FROM direct_message m JOIN app_user sender ON sender.id = m.sender_id
WHERE m.conversation_id = #{conversationId}
ORDER BY m.created_at ASC
LIMIT #{limit} OFFSET #{offset}
